# turnover of daily cross-sectional ranks (Spearman adjacent)
a=[]
for d in sig.index[1:]:
 x,y=sig.shift(1).loc[d],sig.loc[d]; z=pd.concat([x,y],axis=1).dropna()
 if len(z)>=8: a.append(1-z.iloc[:,0].rank().corr(z.iloc[:,1].rank()))
