 d=D[s]; c=d['close'].astype(float); r=c.pct_change(); down=r.where(r<0,0).rolling(40).std(); up=r.where(r>0,0).rolling(40).std()
 f=(c/c.shift(40)-1)/(down+1e-8)*(1+up/(down+1e-8)).clip(.5,2.5); fr=c.shift(-h)/c-1
 return pd.DataFrame({'f':f,'fr':fr},index=pd.to_datetime(d['date']))
