 if len(z)>=8:
  for s in z.index: out.append([dt,s,signal.loc[dt,s]])
pd.DataFrame(out,columns=['date','symbol','signal']).to_csv('scripts/miner_2_20310807_vix_conditioned_reversal_signal.csv',index=False)

