import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data,get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def get(s):
 for fn in (get_stock_daily_data,get_index_daily_data):
  try:
   x=fn(symbol=s,days=5000)
   if x is not None and len(x)>300:return x[['date','close']]
  except:pass
p={s:get(s) for s in U};p={s:x for s,x in p.items() if x is not None}
c=pd.concat([x.set_index('date').close.rename(s) for s,x in p.items()],axis=1).sort_index().ffill(); r=c.pct_change(); r60=c/c.shift(60)-1
down=r.where(r<0).pow(2).rolling(60).mean().pow(.5)*np.sqrt(252)
sig=(-r60/down.replace(0,np.nan)).shift(1)
for h in [10,20,40,60]:
 f=c.shift(-h)/c-1;qs=[];ns=[]
 for d in sig.index:
  z=pd.concat([sig.loc[d].rename('s'),f.loc[d].rename('f')],axis=1).dropna()
  if len(z)>=8:
   q=z.corr(method='spearman').iloc[0,1]
   if np.isfinite(q):qs.append(q);ns.append(len(z))
 q=pd.Series(qs);print(h,'dates',len(q),'avg_n',round(np.mean(ns),2),'IC',round(q.mean(),6),'ICIR',round(q.mean()/q.std(ddof=1),6),'hit',round((q>0).mean(),4))
print('assets',len(p),'dates',len(c),'coverage',round(sig.notna().mean().mean(),4));rank=sig.rank(axis=1,pct=True);print('turnover_proxy',round(rank.diff().abs().mean(axis=1).dropna().mean(),6));sig.to_csv('scripts/miner_2_20330106_downside_reversal_signal.csv',index_label='date')

import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
px={}
for s in U:
 d=get_stock_daily_data(s,days=4600)
 if d is not None and len(d)>300: px[s]=d[['date','close']].dropna().drop_duplicates('date').set_index('date').close.astype(float)
p=pd.DataFrame(px).sort_index(); r=p.pct_change()
ret=p.pct_change(40); vol=r.rolling(40,min_periods=30).std()*np.sqrt(252); path=r.abs().rolling(40,min_periods=30).sum()
# Negative trend efficiency: favor assets whose directional move is weak relative to path and volatility.
f=(-ret/(path+1e-8)/(vol+0.05)).shift(1).replace([np.inf,-np.inf],np.nan)
print('DATA dates',len(p),'instruments',len(px),'range',p.index.min(),p.index.max())
for h in [10,20,40,60]:
 fr=p.shift(-h)/p-1; qs=[];ns=[];ds=[]
 for dt in f.index:
  z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
  if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1:
   qs.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'));ns.append(len(z));ds.append(dt)
 q=pd.Series(qs,index=pd.to_datetime(ds)).dropna()
 print('H %d dates %d avgN %.2f IC %.6f ICIR %.6f hit %.4f'%(h,len(q),np.mean(ns),q.mean(),q.mean()/q.std(),(q>0).mean()))
 if h==60:
  for a,b in [('2020-01-01','2023-12-31'),('2024-01-01','2026-12-31'),('2027-01-01','2029-12-31'),('2030-01-01','2030-12-31'),('2031-01-01','2032-12-31')]:
   z=q.loc[a:b]
   if len(z): print('REGIME',a[:4],len(z),'IC %.6f ICIR %.6f hit %.4f'%(z.mean(),z.mean()/z.std(),(z>0).mean()))
print('COVERAGE %.6f TURNOVER %.6f'%(f.notna().mean().mean(),f.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean()))
out=f.stack().rename('signal').reset_index();out.columns=['date','symbol','signal'];out.to_csv('scripts/miner_2_20330120_trend_efficiency_reversal_signal.csv',index=False)

