import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data

U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
frames={}
for s in U:
    d=get_index_daily_data(s, days=5000)
    if d is not None and len(d)>100:
        d=d[['date','close']].copy().sort_values('date').drop_duplicates('date')
        d['r20']=d.close.pct_change(20)
        d['v20']=d.close.pct_change().rolling(20).std()*np.sqrt(252)
        # completed-session lag: signal at t uses data through t-1
        d['fac']=(d.r20/(d.v20+0.05)).shift(1)
        for h in [10,20,40,60]: d[f'fwd{h}']=d.close.shift(-h)/d.close-1
        frames[s]=d
all_dates=sorted(set().union(*[set(x.date) for x in frames.values()]))
print('symbols',len(frames),'date_range',all_dates[0],all_dates[-1])
for h in [10,20,40,60]:
    vals=[]; ns=[]
    for dt in all_dates:
        z=[]
        for s,d in frames.items():
            q=d[d.date==dt]
            if len(q) and np.isfinite(q.iloc[0].fac) and np.isfinite(q.iloc[0][f'fwd{h}']): z.append((q.iloc[0].fac,q.iloc[0][f'fwd{h}']))
        if len(z)>=8:
            a=np.array(z); c=np.corrcoef(a[:,0],a[:,1])[0,1]
            if np.isfinite(c): vals.append(c); ns.append(len(z))
    x=np.array(vals)
    print('H',h,'dates',len(x),'avgN',np.mean(ns),'IC %.6f ICIR %.6f hit %.4f'%(x.mean(),x.mean()/(x.std(ddof=1)+1e-12),np.mean(x>0)))
    if h==60:
      for label,lo,hi in [('2024','2024-01-01','2024-12-31'),('2027-29','2027-01-01','2029-12-31'),('2030','2030-01-01','2030-12-31'),('2031-32','2031-01-01','2032-12-31'),('2033','2033-01-01','2033-05-25')]:
       y=np.array([v for v,dt in zip(vals,[dt for dt in all_dates if False])]) if False else None
       # recompute filtered using stored date list
       pass
# turnover and coverage on common dates
sig=[]
for dt in all_dates:
 z=[]
 for s,d in frames.items():
  q=d[d.date==dt]
  if len(q) and np.isfinite(q.iloc[0].fac): z.append(q.iloc[0].fac)
 if len(z)>=8: sig.append(np.array(z))
changes=[]
for a,b in zip(sig[:-1],sig[1:]):
 n=min(len(a),len(b)); changes.append(np.mean(np.sign(a[:n])!=np.sign(b[:n])))
print('coverage_valid_date_fraction',len(sig)/len(all_dates),'turnover_sign',np.mean(changes) if changes else np.nan)
# regime 60d with explicit date tracking
out=[]
for dt in all_dates:
 z=[]
 for s,d in frames.items():
  q=d[d.date==dt]
  if len(q) and np.isfinite(q.iloc[0].fac) and np.isfinite(q.iloc[0].fwd60): z.append((q.iloc[0].fac,q.iloc[0].fwd60))
 if len(z)>=8: out.append((dt,np.corrcoef(np.array(z).T)[0,1]))
for label,lo,hi in [('2024','2024-01-01','2024-12-31'),('2027-29','2027-01-01','2029-12-31'),('2030','2030-01-01','2030-12-31'),('2031-32','2031-01-01','2032-12-31'),('2033','2033-01-01','2033-05-25')]:
 x=np.array([v for dt,v in out if str(lo)<=str(dt)<=str(hi)])
 print('REG',label,'n',len(x),'IC',x.mean() if len(x) else np.nan)

